function printElem(elem)
{
    var mywindow = window.open('', 'PRINT', 'height=800,width=756');

    mywindow.document.write('<html><head><title></title>');
    mywindow.document.write('</head><body>');
    mywindow.document.write(document.getElementById(elem).innerHTML);
    mywindow.document.write('</body></html>');

    mywindow.document.close(); // necessary for IE >= 10
    mywindow.focus(); // necessary for IE >= 10*/

    var isChrome = Boolean(mywindow.chrome);
    if (isChrome) {
        mywindow.print();
        setTimeout(function () {
            mywindow.close();
        }, 1000);
    }
    else {
        mywindow.print();
        mywindow.close();
    }

    return true;
}

function previewPrint() {
    $.ajax({
        url: '/ajax/my/booking/getEmailContentBooking.json?bookingid='+ $('#bookingid').val() ,
        type: 'GET',
        contentType: "application/json",
        success: function(result) {
            if (result.emailContent != null) {
                $('#printContent').html(result.emailContent);
            }
        }
    });
    $('#previewPrintModal').modal('show');
}

$(document).ready(function() {
    $('.actionBtn').on('click',function () {
        var action = $(this).data('action');
        $("#actionForm").find('input[name="action"]').val(action);
        $('#actionFormModalLabel').html($(this).data('name'));
        if (action == 'paid') {
            $('#paymentinfoLabel').html("Mã thanh toán");
        } else if(action == 'materialoutput') {
            window.location.href = '/my/booking/' + $('#bookingid').val() + "/material-output.html";
        } else {
            $('#paymentinfoLabel').html('Thông tin thêm');
        }
        $('#actionFormModal').modal('show');
    });
    $('.btn-action-submit').on('click',function () {
        $("#actionForm").submit();
    });

    $('.btn-action-print').on('click', function () {
        printElem('printContent');
    });
});
